{
 "fixed": [
  {
   "name": "Last Copy Reports",
   "description": "The system must provide last-copy reports identifying items that are the only copy within a selected scope, including an individual library and the entire consortium. Reports must also identify deleted items that were the last copy in a library system or facility, supporting catalogers' WorldCat updates.",
   "priority": "High"
  },
  {
   "name": "Administer Report Permissions",
   "description": "The system must provide fine-grained, role-administered permissions controlling who may create, clone, run, and access reports. Administrators must be able to create shared folders that allow or disallow access to specific reports and ad hoc reports on specified data sets.",
   "priority": "High"
  },
  {
   "name": "Assistive Technology Access",
   "description": "The system must support screen readers, screen-magnification software, and other assistive technologies, including JAWS, NVDA, and ZoomText, and comply with Section 508 accessibility requirements.",
   "priority": "High"
  },
  {
   "name": "Client Access Platforms",
   "description": "The system must be accessible through a web browser or a Windows-compatible client.",
   "priority": "High"
  },
  {
   "name": "Consortium Scale Support",
   "description": "The system must support a library consortium with 286 locations, 17 million annual circulations, and purchasing or processing more than 900,000 items per year.",
   "priority": "High"
  },
  {
   "name": "Financial Audit Compliance",
   "description": "The system's reports and archived data must comply with standard accounting practice and applicable state, county, and municipal auditing requirements.",
   "priority": "High"
  },
  {
   "name": "Non-Disruptive Report Processing",
   "description": "The system must process searches and reports during open hours without disrupting other system functions, including circulation and patron access to the OPAC. Long-running reports must be capable of background processing or other isolation from operational activity.",
   "priority": "High"
  },
  {
   "name": "Online System Help",
   "description": "The system must provide online HTML help that is hierarchical, cross-linked, and describes and illustrates system functions. Staff must be able to find help without leaving the system, and the help must be accessible to screen-reader users.",
   "priority": "High"
  },
  {
   "name": "Payment Audit Ledger",
   "description": "The system must maintain a ledger of patron payments identifying the specific charges to which each payment was applied, so finance staff can trace payments and reconcile accounts.",
   "priority": "High"
  },
  {
   "name": "Preserve OPAC Functionality",
   "description": "Management reporting functionality must not constrain or adversely affect the functionality or performance of the Online Public Access Catalog.",
   "priority": "High"
  },
  {
   "name": "Privacy-Protecting Transaction Archives",
   "description": "The system must archive transaction data for the period required by applicable law while protecting patron privacy by removing personally identifiable information and retaining useful demographic statistics.",
   "priority": "High"
  },
  {
   "name": "Record Data Specifications",
   "description": "Product documentation must provide complete data specifications for authority, bibliographic, order, item, hold/request, and other records maintained or accessed by the Management Processes, including field names, data types, and relationships.",
   "priority": "High"
  },
  {
   "name": "Relational Database Support",
   "description": "The system must use and work with a fully relational database structure and support reporting queries across relational data. It must not require a denormalized reporting schema synchronized with the live database.",
   "priority": "High"
  },
  {
   "name": "Role-Based Access Control",
   "description": "The system must control user rights through security groups or roles assigned to individuals, workgroups, and staff groups, and allow administrators to manage permissions through role assignment. Roles must support access appropriate to staff, managers, local administrators, and global administrators.",
   "priority": "High"
  },
  {
   "name": "Server Operating Environment",
   "description": "The system must operate on Linux or Solaris servers, including the Linux and Solaris environments used for production and disaster recovery.",
   "priority": "High"
  },
  {
   "name": "Standards-Compliant HTML",
   "description": "The system must produce standards-compliant HTML for web interfaces, help content, and report output.",
   "priority": "High"
  },
  {
   "name": "Transit Location Reports",
   "description": "The system must report items in transit by sending library and destination library, and provide reports of items currently in transit between locations for delivery coordination.",
   "priority": "High"
  },
  {
   "name": "Enforce Archive Retention",
   "description": "The system must enforce data-archiving retention policies required for audits, including a seven-year retention period where applicable under state and local requirements.",
   "priority": "High"
  },
  {
   "name": "Read-Only OPAC Data Access",
   "description": "Management Processes must interact with the OPAC patron interface by querying data such as holds and circulation transactions, without modifying that data.",
   "priority": "High"
  },
  {
   "name": "Material Volume Reporting",
   "description": "The system must report material volume for a specified library at the current time or a selected historical point, separating new acquisitions, items on the shelf, items in circulation, and totals. Users must be able to break results down by categories such as total items, holds, adult fiction, and board books, customize categories, and report volume added in periods such as the last 30, 60, or 90 days.",
   "priority": "Medium"
  },
  {
   "name": "Shelf Space Usage Report",
   "description": "The system must compare, for each material genre and format, the percentage of total circulations, the percentage of the collection, and the percentage of total shelf space. Results must be available per library and system-wide, support date-range comparisons, and provide a side-by-side library comparison view. When shelf-space measurements are unavailable, the system must estimate shelf space using available item dimensions or item count as a proxy.",
   "priority": "Medium"
  },
  {
   "name": "Generate Transfer Pull Lists",
   "description": "The system must generate printable pull lists identifying items selected for transfer so staff can retrieve them for movement.",
   "priority": "Medium"
  },
  {
   "name": "Preview Pending Transfers",
   "description": "Before applying a transfer, the system must show a preview of the proposed changes, including the number of items and their source and destination locations, and require confirmation before making the changes.",
   "priority": "Medium"
  },
  {
   "name": "Restrict Transfer Permissions",
   "description": "The system must restrict item transfers to authorized roles, including managers, administrators, or transfer coordinators, and prevent unauthorized staff from performing transfers.",
   "priority": "Medium"
  },
  {
   "name": "Save Reusable Queries",
   "description": "The system must allow users to save queries for repeated use, including recurring transfer and reporting tasks.",
   "priority": "Medium"
  },
  {
   "name": "Transfer History Records",
   "description": "The system must retain transfer activity for audit and expose item transfer history so staff can review completed and reverted transfers and determine how often an item has moved.",
   "priority": "Medium"
  },
  {
   "name": "Transfer Item Batches",
   "description": "The system must provide a utility for transferring batches of items between branches or other locations, including mobile libraries, outreach collections, warehouses, book sales, and event locations.",
   "priority": "Medium"
  },
  {
   "name": "Update Item Locations",
   "description": "The system must allow authorized staff to change the location records of selected items to the transfer destination.",
   "priority": "Medium"
  },
  {
   "name": "Delayed Transit Items Report",
   "description": "The system must generate one report of items that have remained in transit longer than a configurable number of days, with views per branch and system-wide. The report must combine transit-to and transit-from items, identify items with no arrival date and an overdue departure date, and allow sorting by due date. Seven days is suggested as the default threshold.",
   "priority": "Medium"
  },
  {
   "name": "Missing Damaged Items Report",
   "description": "The system must provide a report of missing and damaged items by branch. The report must include item condition notes and support date ranges for trend analysis.",
   "priority": "Medium"
  },
  {
   "name": "Audit Record Deletions",
   "description": "The system must retain an audit record of successful deletions, including record type, record identifier, timestamp, user, and user location. This tracking must cover purge activity and other record deletions.",
   "priority": "Medium"
  },
  {
   "name": "Batch Status Conversion",
   "description": "The system must support converting multiple items from one status to another in a batch, such as changing items from missing to discard/weed, and provide a report or workflow to assist with the conversion.",
   "priority": "Medium"
  },
  {
   "name": "Confirm Purge Deletions",
   "description": "The system must require a separate confirmation step before executing purge deletions, distinct from identifying and reviewing candidates.",
   "priority": "Medium"
  },
  {
   "name": "Delete Itemless Records",
   "description": "The system must provide a method to delete records that have no items attached during collection cleanup.",
   "priority": "Medium"
  },
  {
   "name": "Delete Volumes With Copies",
   "description": "The system must provide a method to delete volume entries together with their associated copy entries during collection cleanup.",
   "priority": "Medium"
  },
  {
   "name": "Identify Purge Candidates",
   "description": "The system must identify item records eligible for purging using customizable, combinable criteria, including status (such as missing, discard/weed, or damaged), time spent in a status, and time since last circulation.",
   "priority": "Medium"
  },
  {
   "name": "Include Null Report Values",
   "description": "Report results must include records with null or blank values rather than silently excluding them, including patrons with unpopulated optional demographic fields.",
   "priority": "Medium"
  },
  {
   "name": "Inactive Patron Reports",
   "description": "The system must generate lists of patrons with no circulation or electronic activity during a configurable number of days. Electronic activity includes account or OPAC logins, online holds, online renewals, and logged access to integrated digital collections. Users must be able to select System, Home Library, County, or another required organizational level; include current mailing addresses; separately identify patrons with outstanding fines; exclude specified categories such as do-not-disturb, VIP, staff, or opted-out patrons; and export results to CSV. The report must support background processing and retrieval of completed results.",
   "priority": "Medium"
  },
  {
   "name": "Anonymized Demographic Statistics",
   "description": "The system must produce demographic statistics, including transactions by geographic region and age range, using anonymized data that does not identify individual patrons.",
   "priority": "Medium"
  },
  {
   "name": "Cancel Report Execution",
   "description": "Users must be able to cancel a report that is scheduled or currently running.",
   "priority": "Medium"
  },
  {
   "name": "Collection Value Reports",
   "description": "The system must report item values based on item-record data for the entire collection or a selected portion, including items selected by status, format, collection, call number, or shelving location.",
   "priority": "Medium"
  },
  {
   "name": "Data Quality Reports",
   "description": "The system must provide reports identifying data-quality problems, including items with invalid item types or excessively long call numbers and bibliographic records without item records.",
   "priority": "Medium"
  },
  {
   "name": "Display Report Criteria",
   "description": "The system must display the query selections and clearly defined selection criteria with report results. Results must also identify the report name and selected date criteria.",
   "priority": "Medium"
  },
  {
   "name": "Error Reporting and Feedback",
   "description": "The system must provide high-level error reporting and feedback and low-level query-specific feedback through the front-end interface for Local and Global System Administrators.",
   "priority": "Medium"
  },
  {
   "name": "Group Transaction Reports",
   "description": "The system must group transactions by hour, terminal, branch, and system and support queries for all transactions or transaction types, including check-ins, checkouts, fines collected, and patron registrations.",
   "priority": "Medium"
  },
  {
   "name": "Historical Reporting",
   "description": "The system must support reporting on data as it existed at a specified prior date or date range, including historical shelving locations and snapshots of bills. This reporting capability does not prescribe a particular storage architecture.",
   "priority": "Medium"
  },
  {
   "name": "Item Usage Reports",
   "description": "The system must report total item-use counts and counts for selected date ranges, including fiscal-year and monthly use, and provide last-circulation dates and weeding data such as date of last circulation and circulation count.",
   "priority": "Medium"
  },
  {
   "name": "On-Demand Report Interface",
   "description": "The system must provide an on-demand reporting interface for preset maintenance, collection-development, and similar reports, allowing users to edit selection criteria and display options before execution.",
   "priority": "Medium"
  },
  {
   "name": "Open Template Reporting",
   "description": "The system must provide open-template reporting with circulation, item, patron, bill, and bibliographic attributes available for filtering and display.",
   "priority": "Medium"
  },
  {
   "name": "Prioritize Report Queue",
   "description": "The system must allow designated report types, such as board reports, to be prioritized ahead of lower-priority or resource-consuming reports in the execution queue.",
   "priority": "Medium"
  },
  {
   "name": "Process Description Documentation",
   "description": "Product documentation must provide high-level descriptions of major processes, including bibliographic record import and export, validation against internal and external authority sources, and standard reports.",
   "priority": "Medium"
  },
  {
   "name": "Real-Time Reporting",
   "description": "The system must support reports using current data in real time, including reports used to monitor current activity.",
   "priority": "Medium"
  },
  {
   "name": "Report Output Formats",
   "description": "The system must provide reports in Excel, HTML, CSV, and pivot-table formats.",
   "priority": "Medium"
  },
  {
   "name": "Report Queue Visibility",
   "description": "Staff must be able to view their report's queue position, the number of reports ahead, submission time, and status, including waiting, running, completed, or failed.",
   "priority": "Medium"
  },
  {
   "name": "Single-Row MARC Reporting",
   "description": "The system must extract selected MARC fields for reports and display those fields on a single row of report data, including when the fields are stored across multiple rows.",
   "priority": "Medium"
  },
  {
   "name": "Staff Login Methods",
   "description": "The system must support individual staff authentication using traditional username and password and an optional streamlined method such as an employee-card swipe. Card-based login must not be required or bypass individual authentication, and the system must identify which staff member is logged in.",
   "priority": "Medium"
  },
  {
   "name": "Supported Web Browsers",
   "description": "When accessed through a web browser, the system must support Microsoft Internet Explorer version 6.0 or later and Mozilla Firefox version 2.0 or later.",
   "priority": "Medium"
  },
  {
   "name": "Transaction History Retention",
   "description": "The system must retain detailed transaction history for a configurable number of days and retain monthly and annual aggregate information indefinitely.",
   "priority": "Medium"
  },
  {
   "name": "Transaction Summary Reports",
   "description": "The system must report holds placed, holds filled, and checkouts per patron, library, selected group of libraries, system, or county. Reports must display checkout and placed-hold counts per patron and subtotal holds by type, including active, frozen, and frozen-until holds.",
   "priority": "Medium"
  },
  {
   "name": "Workstation Transaction Reports",
   "description": "The system must report transactions by specified date and time, workstation, or staff member to support analysis of activity and staff workflow.",
   "priority": "Medium"
  },
  {
   "name": "Vendor Data Integration",
   "description": "The system must support data exchange with vendor websites through published APIs or automated transfers of standard-format data files, including USMARC21 and EDIFACT, while accommodating locations where particular vendor data is unavailable.",
   "priority": "Medium"
  },
  {
   "name": "Prevent Duplicate Export Rows",
   "description": "Report exports must avoid unintended duplicate rows so exported data can be used without repeated records.",
   "priority": "Medium"
  },
  {
   "name": "Alert Transfer Problems",
   "description": "The system must notify responsible staff when an item transfer is delayed or encounters an issue.",
   "priority": "Low"
  },
  {
   "name": "Print Transit Labels",
   "description": "The system must generate printable transit labels containing barcodes for items being transferred.",
   "priority": "Low"
  },
  {
   "name": "Share Transfer Queries",
   "description": "The system must allow authorized users to share saved transfer queries with other authorized users.",
   "priority": "Low"
  },
  {
   "name": "Undo Completed Transfers",
   "description": "The system must allow an authorized user to undo an item transfer when an incorrect transfer has been completed.",
   "priority": "Low"
  },
  {
   "name": "Review Purge Candidates",
   "description": "The system must provide read-only reports of item records identified as purge candidates so users can review them without changing or deleting records through the reports.",
   "priority": "Low"
  },
  {
   "name": "Report Deletion Activity",
   "description": "The system must report deletion activity for a selected period, including totals and breakdowns by record type, location, system, and user, and identify users with the highest deletion counts.",
   "priority": "Low"
  },
  {
   "name": "Track Denied Deletions",
   "description": "The system must track deletion attempts that are denied so administrators can identify attempted deletions of records that users should not delete.",
   "priority": "Low"
  },
  {
   "name": "Comparative Report Columns",
   "description": "The system must support report outputs with comparative columns for periods such as last month's circulation, the previous month's circulation, percentage difference, the corresponding month of the previous year, and percentage difference between those periods.",
   "priority": "Low"
  },
  {
   "name": "Edit Canned Report Displays",
   "description": "Authorized users must be able to add canned reports according to their permissions and edit canned-report display fields, such as adding shelving location.",
   "priority": "Low"
  },
  {
   "name": "Email Report Delivery",
   "description": "The system must allow users to deliver reports by email, enter recipients, and select recipients from an address book of regularly used addresses.",
   "priority": "Low"
  },
  {
   "name": "Filter Surveys By Name",
   "description": "Users must be able to select a survey by its name rather than entering its identifier, and the system must resolve the name to the corresponding survey record.",
   "priority": "Low"
  },
  {
   "name": "In-House Use Reports",
   "description": "The system must report non-cataloged in-house use counts by month and cataloged in-house use counts.",
   "priority": "Low"
  },
  {
   "name": "Notice Activity Reports",
   "description": "The system must support reports on pre-overdue notices, overdue notices, and holds notices sent.",
   "priority": "Low"
  },
  {
   "name": "Patron Behavior Statistics",
   "description": "The system must produce statistics for understanding and predicting patron behavior and material use, including average return speed for a particular book, likelihood of renewal, renewal rates, and the percentage of branch checkouts that are renewals.",
   "priority": "Low"
  },
  {
   "name": "Report Hold Placement Methods",
   "description": "The system must count hold requests and report how each hold was placed, including at a staff desk, at a public computer inside the library, or remotely.",
   "priority": "Low"
  },
  {
   "name": "Upload Report Filters",
   "description": "Users must be able to upload a text file containing values such as barcodes or TCNs and use those values to filter a report.",
   "priority": "Low"
  }
 ],
 "items": [
  {
   "index": 1,
   "name": "Multi-Record Query Interface",
   "description": "The system must provide a user-friendly query-design interface for bibliographic, item, patron, transaction, and financial records. Users must be able to select fields, choose values from picklists, select regular expressions from a dropdown, and use Boolean operators.",
   "source_doc_ids": [
    "D10",
    "D12",
    "D18"
   ],
   "source_priority_note": null
  },
  {
   "index": 2,
   "name": "Table and Field Access Control",
   "description": "The system must allow administrators to control staff access to tables and fields.",
   "source_doc_ids": [
    "D10",
    "D12",
    "D18"
   ],
   "source_priority_note": null
  },
  {
   "index": 3,
   "name": "Branch Capacity Interface",
   "description": "The system must provide authorized users, including branch managers, with an overview of capacity across all Branches using a defined capacity measure, with the ability to drill into individual Branches, sort and filter by region, library type, and current load, view growth or shrinkage trends, and export the information to CSV.",
   "source_doc_ids": [
    "D02",
    "D10",
    "D17"
   ],
   "source_priority_note": null
  },
  {
   "index": 4,
   "name": "Revert Transferred Items",
   "description": "The system must automatically or manually return transferred Items to their original Branches after a configured period or when configured criteria are met, including time-based conditions and Item-status or destination events.",
   "source_doc_ids": [
    "D04",
    "D10",
    "D15",
    "D20"
   ],
   "source_priority_note": "D04 calls automatic reversion important"
  },
  {
   "index": 5,
   "name": "Query and Select Transfer Candidates",
   "description": "The system must allow authorized staff to query candidate materials for transfer or other administrative processing using conditions such as material type, section, genre, or circulation history, and to manually select individual titles or items, including only part of a larger candidate set, for subsequent processing.",
   "source_doc_ids": [
    "D04",
    "D15",
    "D20"
   ],
   "source_priority_note": null
  },
  {
   "index": 6,
   "name": "Bibliographic Record Counts",
   "description": "The system must report counts of bibliographic records, including records added by each user and library.",
   "source_doc_ids": [
    "D10",
    "D14"
   ],
   "source_priority_note": null
  },
  {
   "index": 7,
   "name": "Edited Record Counts",
   "description": "The system must report counts of edited bibliographic records.",
   "source_doc_ids": [
    "D10",
    "D14"
   ],
   "source_priority_note": null
  },
  {
   "index": 8,
   "name": "Records Without Volumes",
   "description": "The system must report bibliographic records without attached volumes.",
   "source_doc_ids": [
    "D10",
    "D14"
   ],
   "source_priority_note": null
  },
  {
   "index": 9,
   "name": "Missing MARC Fields",
   "description": "The system must report bibliographic records missing specified MARC fields.",
   "source_doc_ids": [
    "D10",
    "D14"
   ],
   "source_priority_note": null
  },
  {
   "index": 10,
   "name": "Current Bills Report",
   "description": "The system must provide a report of bills currently owed by patrons.",
   "source_doc_ids": [
    "D10",
    "D14"
   ],
   "source_priority_note": null
  },
  {
   "index": 11,
   "name": "Payments Received Report",
   "description": "The system must provide a detailed report of payments received.",
   "source_doc_ids": [
    "D10",
    "D14"
   ],
   "source_priority_note": null
  },
  {
   "index": 12,
   "name": "Forgive Work Goods Report",
   "description": "The system must provide a detailed report of forgive, work, and goods payments.",
   "source_doc_ids": [
    "D10",
    "D14"
   ],
   "source_priority_note": null
  },
  {
   "index": 13,
   "name": "Voids Report",
   "description": "The system must provide a detailed report of voids.",
   "source_doc_ids": [
    "D10",
    "D14"
   ],
   "source_priority_note": null
  },
  {
   "index": 14,
   "name": "Aged Debt Report",
   "description": "The system must provide an aged-debt report with detailed debt information.",
   "source_doc_ids": [
    "D14"
   ],
   "source_priority_note": null
  },
  {
   "index": 15,
   "name": "Run and Schedule Canned Reports",
   "description": "The system must provide canned reports that users can run immediately or schedule to run ASAP, hourly, daily, weekly, monthly, or yearly. Users must be able to edit recurring reports by adding or removing report selections and changing the report's email recipients.",
   "source_doc_ids": [
    "D10",
    "D14",
    "D20"
   ],
   "source_priority_note": null
  },
  {
   "index": 16,
   "name": "Combine Reports Into Documents",
   "description": "The system must allow users to select multiple canned reports to run together and view their results in one document.",
   "source_doc_ids": [
    "D10",
    "D14",
    "D20"
   ],
   "source_priority_note": null
  },
  {
   "index": 17,
   "name": "Circulation Transaction Counts",
   "description": "The system must provide circulation reports with individual and cumulative counts for check-ins by book drop, terminal, staff user, and self-service method, distinguish check-ins from renewals in check-in date and time reporting, and count checkouts and renewals by staff checkout, self-checkout, staff renewal, self-checkout renewal, online renewal, and OPAC renewal.",
   "source_doc_ids": [
    "D10",
    "D14",
    "D20"
   ],
   "source_priority_note": null
  },
  {
   "index": 18,
   "name": "Overdue Item Reports",
   "description": "The system must provide reports of overdue items with relevant contact information.",
   "source_doc_ids": [
    "D10",
    "D14",
    "D20"
   ],
   "source_priority_note": null
  },
  {
   "index": 19,
   "name": "Circulation Attribute Breakdowns",
   "description": "The system must provide circulation reports broken down by modifier, category, Dewey classification, shelving location, MARC fields, patron county, home library, and age.",
   "source_doc_ids": [
    "D10",
    "D14",
    "D20"
   ],
   "source_priority_note": null
  },
  {
   "index": 20,
   "name": "Cataloged Circulation Totals",
   "description": "The system must provide reports of non-cataloged circulation and total circulation, including combined counts for cataloged and non-cataloged circulation.",
   "source_doc_ids": [
    "D10",
    "D14",
    "D20"
   ],
   "source_priority_note": null
  },
  {
   "index": 21,
   "name": "State-Aid Statistics Reports",
   "description": "The system must provide predefined reports for library boards and other external consumers containing the basic statistics required by the Georgia Annual Report and Application for State Aid.",
   "source_doc_ids": [
    "D10",
    "D12",
    "D18"
   ],
   "source_priority_note": null
  },
  {
   "index": 22,
   "name": "Cross-Tabulated Activity Reports",
   "description": "The system must provide predefined activity reports containing checkouts, check-ins, holds placed, and holds filled, with cross-tabulation by terminal, Branch, system, hour, Patron age range, Patron type, and Patron location.",
   "source_doc_ids": [
    "D10",
    "D12",
    "D18"
   ],
   "source_priority_note": null
  },
  {
   "index": 23,
   "name": "Patron Account Balance Reports",
   "description": "The system must report patron account balances by patron, home library, and system.",
   "source_doc_ids": [
    "D10",
    "D11"
   ],
   "source_priority_note": null
  },
  {
   "index": 24,
   "name": "Fines and Charges Reports",
   "description": "The system must report fines and charges by time period and charge type.",
   "source_doc_ids": [
    "D10",
    "D11"
   ],
   "source_priority_note": null
  },
  {
   "index": 25,
   "name": "Waived Fine Reports",
   "description": "The system must report fines waived by time period and Branch.",
   "source_doc_ids": [
    "D10",
    "D11"
   ],
   "source_priority_note": null
  },
  {
   "index": 26,
   "name": "Payment Reports",
   "description": "The system must report payments by time period, payment method, and collecting library.",
   "source_doc_ids": [
    "D10",
    "D11"
   ],
   "source_priority_note": null
  },
  {
   "index": 27,
   "name": "Hold Purchase Alert Reports",
   "description": "The system must provide reports identifying hold purchase alerts.",
   "source_doc_ids": [
    "D10",
    "D14"
   ],
   "source_priority_note": null
  },
  {
   "index": 28,
   "name": "Hold Shipment Reports",
   "description": "The system must provide reports of items sent or received for holds.",
   "source_doc_ids": [
    "D10",
    "D14"
   ],
   "source_priority_note": null
  },
  {
   "index": 29,
   "name": "IntraPINES Loan Reports",
   "description": "The system must provide reports of IntraPINES loans by system or facility.",
   "source_doc_ids": [
    "D10",
    "D14"
   ],
   "source_priority_note": null
  },
  {
   "index": 30,
   "name": "Hold Fulfillment Reports",
   "description": "The system must provide reports of unfilled holds, annual hold counts, and stale holds awaiting pickup.",
   "source_doc_ids": [
    "D10",
    "D14"
   ],
   "source_priority_note": null
  },
  {
   "index": 31,
   "name": "Item Activity Reports",
   "description": "The system must provide item reports for items added, deleted, edited, counted, currently checked out, overdue, long overdue, missing, in transit, claimed returned, or created within a date range. These item reports must show the last edit date based only on item edits, and circulation activity must not change or be included in that date.",
   "source_doc_ids": [
    "D10",
    "D14",
    "D15"
   ],
   "source_priority_note": null
  },
  {
   "index": 32,
   "name": "Item Selection And Weeding Reports",
   "description": "The system must provide item reports that select items by use count or fines-stopped reason and provide weeding information.",
   "source_doc_ids": [
    "D10",
    "D14"
   ],
   "source_priority_note": null
  },
  {
   "index": 33,
   "name": "Deleted Last-Copy Reports",
   "description": "The system must provide reports identifying deleted last copies of items.",
   "source_doc_ids": [
    "D10",
    "D14"
   ],
   "source_priority_note": null
  },
  {
   "index": 34,
   "name": "Collection Age And Value Reports",
   "description": "The system must provide reports showing collection age or value by call number or shelving location.",
   "source_doc_ids": [
    "D10",
    "D14"
   ],
   "source_priority_note": null
  },
  {
   "index": 35,
   "name": "Associate Financial Records",
   "description": "The system must associate fines, charges, waivers, and ecommerce transactions with Patron and Item records.",
   "source_doc_ids": [
    "D10",
    "D11"
   ],
   "source_priority_note": null
  },
  {
   "index": 36,
   "name": "Query Financial Records",
   "description": "The system must support financial queries that join fines, charges, waivers, and ecommerce transactions with Patron and Item records and allow users to query accounts above a specified balance.",
   "source_doc_ids": [
    "D10",
    "D11"
   ],
   "source_priority_note": null
  },
  {
   "index": 37,
   "name": "Update Financial Information",
   "description": "The system must allow financial information to be updated and reflected promptly.",
   "source_doc_ids": [
    "D10",
    "D11"
   ],
   "source_priority_note": null
  },
  {
   "index": 38,
   "name": "Track Library Payments",
   "description": "The system must track fines waived and payments by library.",
   "source_doc_ids": [
    "D10",
    "D11"
   ],
   "source_priority_note": null
  },
  {
   "index": 39,
   "name": "Create Staff Report Templates",
   "description": "Administrators must be able to create report templates that are available to staff.",
   "source_doc_ids": [
    "D10",
    "D12",
    "D17",
    "D20"
   ],
   "source_priority_note": null
  },
  {
   "index": 40,
   "name": "Modify Permitted Report Selections",
   "description": "Staff must be able to run report templates as-is or modify only permitted selections, with changes preserving dependable results.",
   "source_doc_ids": [
    "D10",
    "D12",
    "D17",
    "D20"
   ],
   "source_priority_note": null
  },
  {
   "index": 41,
   "name": "Create PINES-Wide Templates",
   "description": "Authorized users must be able to create report templates for PINES libraries.",
   "source_doc_ids": [
    "D10",
    "D12",
    "D17",
    "D20"
   ],
   "source_priority_note": null
  },
  {
   "index": 42,
   "name": "Clone Report Template Variants",
   "description": "Authorized users must be able to clone an existing report template into a separate variant.",
   "source_doc_ids": [
    "D10",
    "D12",
    "D17",
    "D20"
   ],
   "source_priority_note": null
  },
  {
   "index": 43,
   "name": "Patron Count Reports",
   "description": "The system must provide reports for patron counts and patron additions.",
   "source_doc_ids": [
    "D10",
    "D14"
   ],
   "source_priority_note": null
  },
  {
   "index": 44,
   "name": "Patron Demographic Reports",
   "description": "The system must provide reports of patrons by demographic category, age, county, city, ZIP code, home library, and profile group.",
   "source_doc_ids": [
    "D10",
    "D14"
   ],
   "source_priority_note": null
  },
  {
   "index": 45,
   "name": "Patron Status Reports",
   "description": "The system must provide reports of patrons by survey response, expiration date, inactive or barred status, and note wording, as well as reports of voter survey responses.",
   "source_doc_ids": [
    "D10",
    "D14"
   ],
   "source_priority_note": null
  },
  {
   "index": 46,
   "name": "Staff Account Reports",
   "description": "The system must provide reports of staff accounts by password-change date and account expiration.",
   "source_doc_ids": [
    "D10",
    "D14"
   ],
   "source_priority_note": null
  },
  {
   "index": 47,
   "name": "Bibliographic Record Reports",
   "description": "The system must provide periodic management reports identifying bibliographic records with holds and bibliographic records without item records.",
   "source_doc_ids": [
    "D10"
   ],
   "source_priority_note": null
  },
  {
   "index": 48,
   "name": "Item Status Reports",
   "description": "The system must provide periodic management reports identifying items that have not been checked out for a specified number of days, items with item-level holds, in-transit items with outstanding holds, last copies, and missing items.",
   "source_doc_ids": [
    "D10"
   ],
   "source_priority_note": null
  },
  {
   "index": 49,
   "name": "Item Catalog Validation Reports",
   "description": "The system must provide periodic management reports identifying items with invalid item types and items with long call numbers.",
   "source_doc_ids": [
    "D10"
   ],
   "source_priority_note": null
  },
  {
   "index": 50,
   "name": "Patron Library Validation Reports",
   "description": "The system must provide periodic management reports identifying patrons with invalid home libraries.",
   "source_doc_ids": [
    "D10"
   ],
   "source_priority_note": null
  },
  {
   "index": 51,
   "name": "Filter Patron Reports",
   "description": "The system must allow patron queries and reports to be limited by age ranges calculated from Patrons' birth dates, ZIP code, county of residence, home Branch, patron type, and preferred language. Users must be able to configure the age brackets used for filtering, including user-defined brackets such as 0–5, 6–10, and 11–15, and combine these filters with other conditions using AND and OR logic.",
   "source_doc_ids": [
    "D08",
    "D10"
   ],
   "source_priority_note": "D08 describes these reports as essential for program planning"
  },
  {
   "index": 52,
   "name": "Group Patron Reports",
   "description": "The system must group patron queries and reports by age ranges calculated from Patrons' birth dates, ZIP code, county of residence, home Branch, patron type, and preferred language, using configurable age brackets such as 0–5, 6–10, and 11–15, and show aggregates such as circulation counts and patron counts for each group.",
   "source_doc_ids": [
    "D08",
    "D10"
   ],
   "source_priority_note": "D08 describes these reports as essential for program planning"
  },
  {
   "index": 53,
   "name": "Separate System Environments",
   "description": "The system must provide separate development, training, and production environments, with the training environment allowing staff to practice without risking production data.",
   "source_doc_ids": [
    "D10",
    "D16",
    "D18",
    "D19"
   ],
   "source_priority_note": "D10 marks development and training environments with configuration migration Medium Priority"
  },
  {
   "index": 54,
   "name": "Configuration Migration",
   "description": "The system must allow configurations such as report templates, permissions, and saved queries to be migrated into the production environment.",
   "source_doc_ids": [
    "D10",
    "D16",
    "D18",
    "D19"
   ],
   "source_priority_note": "D10 marks development and training environments with configuration migration Medium Priority"
  },
  {
   "index": 55,
   "name": "Track Uncataloged Material Inventory",
   "description": "The system must track uncataloged materials, including paperback books and children's board books, as inventory before individual catalog records are complete.",
   "source_doc_ids": [
    "D10",
    "D15"
   ],
   "source_priority_note": null
  },
  {
   "index": 56,
   "name": "Distribute Materials Rapidly",
   "description": "The system must support rapid distribution of uncataloged materials with minimal Branch labor.",
   "source_doc_ids": [
    "D10",
    "D15"
   ],
   "source_priority_note": null
  },
  {
   "index": 57,
   "name": "Identify Material Use",
   "description": "The system must identify the use of uncataloged materials.",
   "source_doc_ids": [
    "D10",
    "D15"
   ],
   "source_priority_note": null
  },
  {
   "index": 58,
   "name": "Report Uncataloged Material Transactions",
   "description": "The system must include transactions involving uncataloged materials in circulation statistics and reports.",
   "source_doc_ids": [
    "D10",
    "D15"
   ],
   "source_priority_note": null
  },
  {
   "index": 59,
   "name": "Configuration Migration",
   "description": "The reporting system must provide export and import functionality to migrate configurations between environments, including configurations developed in development or training for use in production, report templates, permission settings, and other configuration.",
   "source_doc_ids": [
    "D16",
